// Package spellcast only holds the embedded static assets, because go:embed
// cannot reach outside the package directory and the entry point lives in cmd/spellcast.
package spellcast

import "embed"

// Frontend is the built result-window UI (frontend/dist).
//
//go:embed all:frontend/dist
var Frontend embed.FS

// TrayIcon is the system tray / app icon.
//
//go:embed build/appicon.png
var TrayIcon []byte

// Notices holds the licenses of the bundled third-party software
// (generated by scripts/gen-notices.sh, shown in the About window).
//
//go:embed THIRD_PARTY_NOTICES.txt
var Notices string
